    (hG : G.FullyFaithful) (hH : H.FullyFaithful)
    (α : G ⋙ L₂ ≅ L₁ ⋙ H)
    (himage : ∀ d, G.essImage (R₂.obj (H.obj d))) :
    IsIso (mateEquiv adj₁ adj₂ (TwoSquare.mk _ _ _ _ α.hom)).natTrans
